NEWKEYS = {"Your plan": ["Jou plan", "Uhlelo lwakho", "Moralo wa hao", "Isicwangciso sakho", "Leano la gago"], "Your plan holds up to 10 regulars on Free, 50 on $5, 200 on $20.": ["Jou plan hou tot 10 vaste klante op Gratis, 50 op $5, 200 op $20.", "Uhlelo lwakho luphatha amakhasimende ajwayelekile afika ku-10 ku-Mahhala, angu-50 ku-$5, angu-200 ku-$20.", "Moralo wa hao o tshwara bareki ba kamehla ho fihla ho 10 ho Mahala, 50 ho $5, 200 ho $20.", "Isicwangciso sakho sithwala abathengi abaqhelekileyo ukuya kuma-10 kwi-Simahla, ama-50 kwi-$5, ama-200 kwi-$20.", "Leano la gago le swara bareki ba ka mehla go fihla go 10 go Mahala, 50 go $5, 200 go $20."]}
ABOUT_ADD = " 27 Sep 2026 (CIRCLE-CAPS-1, RUL-176): the Buzz explainer's 'Your plan' row -- Claude's draft for David's readers."

def _patch(rel):
    p = os.path.join(ROOT, rel); s = io.open(p, encoding="utf-8").read()
    if MARK[rel] in s:
        print("%s: already carries CIRCLE-CAPS-1 -- skipped" % rel); return False
    for old, new in HUNKS[rel]:
        n = s.count(old)
        if n != 1:
            sys.exit("REFUSED %s: an anchor matches %d times -- the file moved under us; nothing written" % (rel, n))
    for old, new in HUNKS[rel]:
        if s.count(old) != 1:
            sys.exit("REFUSED %s: hunks overlap or the file moved -- nothing written" % rel)
        s = s.replace(old, new)
    io.open(p, "w", encoding="utf-8").write(s)
    print("%s: applied %d hunk(s)" % (rel, len(HUNKS[rel]))); return True

def _i18n():
    p = os.path.join(ROOT, "roles", "quick_i18n.json"); j = json.load(io.open(p, encoding="utf-8"))
    add = {k: v for k, v in NEWKEYS.items() if k not in j["w"]}
    if add:
        j["w"].update(add)
        if ABOUT_ADD not in j["_about"]: j["_about"] += ABOUT_ADD
        io.open(p, "w", encoding="utf-8").write(json.dumps(j, ensure_ascii=False, indent=1) + "\n")
    # regenerate the QI18N block exactly as scripts/sync_quick_roles.py does (no pictures touched)
    L = j["langs"]
    d = {"w": {en: dict(zip(L, v)) for en, v in j["w"].items()},
         "p": [dict(zip(["en"] + L, x)) for x in j["p"]],
         "r": [dict(zip(["en"] + L, x)) for x in j["r"]]}
    ib = ("/* QUICK-I18N:BEGIN -- generated by scripts/sync_quick_roles.py from roles/quick_i18n.json; do not edit */\n"
          "var QI18N = %s;\n/* QUICK-I18N:END */" % json.dumps(d, ensure_ascii=False))
    qp = os.path.join(ROOT, "quick.html"); q = io.open(qp, encoding="utf-8").read()
    ipat = re.compile(r"/\* QUICK-I18N:BEGIN.*?/\* QUICK-I18N:END \*/", re.S)
    if not ipat.search(q): sys.exit("quick.html has no QUICK-I18N markers")
    q2 = ipat.sub(lambda m: ib, q)
    if q2 != q: io.open(qp, "w", encoding="utf-8").write(q2)
    io.open(os.path.join(ROOT, "genie", "HARNESS.html"), "w", encoding="utf-8").write(q2)
    print("quick i18n: %d new phrase(s); QI18N block regenerated; genie/HARNESS.html = quick.html" % len(add))

if __name__ == "__main__":
    if not os.environ.get("ROOT"):
        r = subprocess.run([sys.executable, os.path.join(ROOT, "scripts", "work_lock.py"), "check",
                            "bea_main.py", "ms.js", "dashboard.server.html", "quick.html", "route_policy.json"])
        if r.returncode == 3:
            sys.exit("WORK-LOCK-1: another lane holds one of these files -- not applied. Re-run when the lock clears.")
    for rel in ("bea_main.py", "ms.js", "dashboard.server.html", "quick.html", "route_policy.json"):
        _patch(rel)
    _i18n()
    print("done -- now: python3 -m py_compile bea_main.py; node --check ms.js; ledger RG-0510; rulings_check")
